/** 
 * Constructs a  {@link SingletonAssert} for the value of the provided {@link PCollection} with the specified reason. <p>Note that the actual value must be coded by a  {@link KvCoder}, not just any  {@code Coder<K,V>}. 
 */
public static <K,V>SingletonAssert<Map<K,Iterable<V>>> thatMultimap(String reason, PCollection<KV<K,V>> actual) {
  KvCoder<K,V> kvCoder;
  try {
    @SuppressWarnings("unchecked") 
    kvCoder = (KvCoder<K,V>) actual.getCoder();
  } catch (IllegalStateException e) {
    throw new RuntimeException("Failed to retrieve coder for the provided PCollection: " + e.getMessage(), e);
  }
  return new PCollectionViewAssert<>(
    actual, 
    View.asMultimap(), 
    MapCoder.of(kvCoder.getKeyCoder(), IterableCoder.of(kvCoder.getValueCoder())), 
    PAssertionSite.capture(reason)
  );
}
